Egy shell scriptet írok, amely egy Pythonos Replit appban lefutva letölti az apple.com teljes oldalát, és úgy alakítja át az index.htmlt, hogy a CSS és JS tartalmak be legyenek ágyazva benne. A shell script használni fogja a wgetet a teljes oldal letöltésére, majd egy egyszerű Python scriptet a CSS és JS beágyazására.

Íme egy példa megoldás:

bash
#!/bin/bash

# Letöltjük az apple.com teljes weboldalát a current könyvtárba
wget --mirror --convert-links --adjust-extension --page-requisites --no-parent https://www.apple.com/ -P app/

# Python script az index.html feldolgozására (app könyvtárban)
python3 << EOF
import os

app_dir = "app/www.apple.com"
index_path = os.path.join(app_dir, "index.html")

def inline_resource(file_path):
    with open(file_path, 'r', encoding="utf-8", errors='ignore') as f:
        return f.read()

if os.path.exists(index_path):
    with open(index_path, 'r', encoding="utf-8", errors='ignore') as f:
        html = f.read()

    # Beágyazzuk a CSS és JS fájlokat az index.html-be
    import re

    # CSS inline helyettesítés
    def replace_css(match):
        css_path = os.path.join(app_dir, match.group(1))
        if os.path.exists(css_path):
            return "<style>\n" + inline_resource(css_path) + "\n</style>"
        else:
            return match.group(0)

    # JS inline helyettesítés
    def replace_js(match):
        js_path = os.path.join(app_dir, match.group(1))
        if os.path.exists(js_path):
            return "<script>\n" + inline_resource(js_path) + "\n</script>"
        else:
            return match.group(0)

    html = re.sub(r'<link[^>]*href="([^"]+\.css)"[^>]*/?>', replace_css, html)
    html = re.sub(r'<script[^>]*src="([^"]+\.js)"[^>]*></script>', replace_js, html)

    with open
